    ('gangneung-ojukheon', 'บ้านโบราณสมัยโชซอน บ้านเกิดของชินซาอิมดัง/อียุลกก สวนไผ่ดำสวยงาม · เปิด 09:00-17:00 ทุกวัน (มีค่าเข้า)'),
    ('seoul-gyeongbokgung', 'พระราชวังหลักของราชวงศ์โชซอน ใส่ฮันบกเข้าฟรี (ไม่ต้องต่อคิวซื้อตั๋ว) · ไฮไลท์: ลานพระที่นั่งคึนจองจอน (근정전) และศาลากลางน้ำคยองฮเวรู (경회루) · พิธีเปลี่ยนเวรทหารยาม 10:00 และ 14:00 หน้าประตูควังฮวามุน · เปิด 09:00-18:30 (เข้าได้ถึง 17:00) · ⚠️ **ปิดทุกวันอังคาร**'),
    ('seoul-bukchon', 'หมู่บ้านบ้านโบราณฮันอก ตรอกมุมสูงมองเห็น N Seoul Tower อยู่ที่ซอย 북촌로11길 · ⚠️ เป็นเขตควบคุมพิเศษ (คนอยู่จริง) เข้าได้ 10:00-17:00 เท่านั้น และซอย 북촌로11길 ห้ามนักท่องเที่ยวเข้าวันอาทิตย์ · ห้ามส่งเสียงดัง มีเจ้าหน้าที่เดินตรวจ · เดินจากเคียงบกกุง 10 นาที ต่อไปอินซาดง/อิกซอนดงได้'),
    ('seoul-hongdae', 'ย่านวัยรุ่น/มหาลัย ร้านค้า ดนตรีสด บรรยากาศคึกคักตอนเย็น-กลางคืน'),
    ('seoul-yeonnamdong', 'ย่านคาเฟ่/ร้านของแต่งบ้านเก๋ๆ ติดฮงแด บรรยากาศชิลกว่า'),
    ('seoul-myeongdong', 'ย่านช้อปปิ้ง/สตรีทฟู้ดกลางเมือง ที่ตั้งของ Harujae Myeongdong · เสื้อผ้า สตรีทแวร์ เครื่องสำอาง — Olive Young สาขาใหญ่ 명동타운 (명동8길 27 · 10:00-22:30) · ขึ้น N Seoul Tower ได้จากที่นี่ด้วยบัส 01A/01B หรือกระเช้านัมซาน'),
    ('seoul-myeongdong-kyoja', 'ร้านบะหมี่คัลกุกซู (칼국수) + เกี๊ยวนึ่ง (만두) ระดับบิบกูร์มองด์ กินคู่กิมจิกระเทียมเผ็ดจัด · เปิด 10:30-21:00 ทุกวัน · เดินจากใจกลางเมียงดง 2 นาที คิวยาวช่วงเย็น'),
    ('seoul-jd-bbq-itaewon', 'ร้านหมูย่างเตาถ่านย่านอิแทวอน เรตติ้ง 4.9 จากรีวิวกว่า 3,300 — สูงที่สุดในบรรดาร้านอาหารที่เลือกไว้ในทริปนี้ · ☎️ 02-790-1555 · เปิดเย็นอย่างเดียว 17:00-23:50 (จ-ศ) / 16:30-23:50 (ส-อา) · ร้านเล็กและดังมาก ไปรอบแรกที่ร้านเปิดจะไม่ต้องต่อคิว · เดินจากสถานีอิแทวอน (이태원 สาย 6) ~400 ม. · จากเมียงดง: สาย 4 → เปลี่ยนสาย 6 ที่ซัมกักจี ~20 น.'),
    ('seoul-saemaul-hongdae', 'ร้านหมูย่างของเชฟแพคจงวอน อยู่กลางย่านสตรีทแวร์ฮงแด เดินจากยอนนัมดงข้ามมาได้ · เมนูชูโรง 열탄불백 (Yeoltan Bulbaek หมูสไลซ์หมักซอสเผ็ดย่างกระทะ) + 7분 김치찌개 (แกงกิมจิ 7 นาที) คลุกข้าวกับสาหร่าย · เปิด 11:00-15:00 แล้วพัก ก่อนเปิดอีกทีบ่ายสี่ยาวถึง 10:00 เช้าวันรุ่งขึ้น — กินได้ทั้งมื้อเที่ยงและมื้อดึกหลังช้อปเสร็จ'),
    ('seoul-yoojung-sikdang', 'ร้านข้าวบ้านๆ ย่านนนฮยอน/ชินซา ใกล้ตึกค่ายเก่าของ BTS ที่วงมากินกันตั้งแต่ยุคเดบิวต์ ในร้านติดรูปและของสะสมเต็มไปหมด · เมนูเด็ด 방탄유쌈 (Bangtan Yutsam หมูผัดซอสเกาหลีเสิร์ฟพร้อมบิบิมบับ) · เปิด 10:00-21:30 (จ-ศ) / 10:00-20:00 (ส-อา) · เดินจากสถานีอับกูจอง (압구정 สาย 3) ~500 ม.'),
    ('seoul-seongsudong', 'ย่านโรงงานเก่าแปลงเป็นคาเฟ่/แกลเลอรีสไตล์อินดัสเทรียล กำลังฮิต'),
    ('seoul-n-tower', 'จุดชมวิวเมืองโซล 360 องศา สวยตอนพระอาทิตย์ตก-กลางคืน นั่งเคเบิลคาร์ขึ้น'),
    ('seoul-insadong', 'ถนนวัฒนธรรมดั้งเดิม ร้านของฝาก/งานฝีมือ/ร้านชา ใกล้พระราชวัง'),
    ('seoul-ikseondong', 'ตรอกบ้านฮันอกเก่าแปลงเป็นคาเฟ่/ร้านชิคๆ บรรยากาศเก๋ ใกล้สถานี Jongno 3-ga'),
    ('seoul-hanboknam', 'ร้านเช่าฮันบกหน้าประตูวังฝั่งตะวันตก เดินถึงเคียงบกกุง 300 ม. · เปิด 09:00-19:00 ทุกวัน · ใส่ฮันบกเข้าวังฟรีไม่ต้องต่อคิวซื้อตั๋ว · จองคิวล่วงหน้าผ่าน Klook/Trazy ได้สิทธิ์ทำผมฟรี ช่วงไฮซีซั่นใบไม้เปลี่ยนสีคิวยาว · ร้านโทโซกชนอยู่ถัดไป 250 ม. คืนชุดตอนไปกินข้าวเที่ยงได้พอดี'),
    ('seoul-tosokchon', 'ร้านไก่ตุ๋นโสมในตำนานหลังวังเคียงบกกุง เดิน 400 ม. จากประตูตะวันตก · เปิด 10:00-22:00 ทุกวัน ไม่มีวันหยุด · คิวยาวช่วง 12:00-13:00 ไปก่อนเที่ยงจะไม่ต้องรอ'),
    ('seoul-the-hyundai', 'ห้างโมเดิร์นที่สุดของโซล ไฮไลท์คือสวนในร่มชั้น 5 Sounds Forest (사운즈 포레스트) และป๊อปอัปสโตร์ที่หมุนเปลี่ยนตลอด · เปิด 10:30-20:00 (จ-พฤ) / 10:30-20:30 (ศ-อา) · ขอคืนภาษีได้ที่เคาน์เตอร์ในห้าง · เดินไปสวนริมแม่น้ำฮันยออีโดได้ 700 ม.'),
    ('seoul-yeouido-hangang', 'สวนริมแม่น้ำฮันที่คนเกาหลีมานั่งชิลกันจริงๆ · เปิด 24 ชม. · เช่าเสื่อ/เต็นท์ได้หน้าสวน กินรามยอนต้มจากตู้กดริมน้ำ (ราเมนกอน 라면 조리기) มีที่ร้านสะดวกซื้อริมท่าเรือ · พระอาทิตย์ตกกลาง ต.ค. ~18:00 ลมเย็นแล้ว เอาเสื้อคลุมไปด้วย'),
    ('seoul-olive-young-myeongdong', 'สาขาใหญ่สุดของเมียงดง เครื่องสำอาง/สกินแคร์ครบที่สุด มีพนักงานพูดไทยได้บางช่วง · เปิด 10:00-22:30 ทุกวัน · ขอคืนภาษีทันทีที่เคาน์เตอร์ (ยื่นพาสปอร์ตเล่มจริง ซื้อครบ 15,000 วอนขึ้นไป) · อีกสาขาใหญ่ 센트럴 명동타운 (명동8길 27) เดินต่อไป 2 นาที ของหมดที่นี่ไปหาที่นั่นได้'),
    ('seoul-dongdaemun-ddp', 'อาคารทรงล้ำอนาคต ไฟสวยตอนกลางคืน ใกล้ตลาดช้อปปิ้งเปิดดึก Dongdaemun'),
    ('suwon-hwaseong', 'กำแพงเมืองโบราณ มรดกโลก UNESCO ยาว 5.7 กม. เดินได้ 24 ชม. ไม่มีค่าเข้าบนกำแพง · พิกัดนี้คือประตูจางอันมุน (장안문) ประตูเหนือ — ช่วงที่สวยที่สุดคือ ชางรยงมุน → ฮวาฮงมุน → จางอันมุน เดินสบายๆ ~1.5 ชม. · รถรางมังกร Hwaseong Trolley วิ่งจากชางรยงมุนถ้าไม่อยากเดิน'),
    ('suwon-haenglidan', 'ตรอกบ้านโบราณรีโนเวทเลียบกำแพงฮวาซ็อง เต็มไปด้วยคาเฟ่/ร้านของแต่งบ้าน ตามรอยซีรีส์ Extraordinary Attorney Woo (ร้านคิมบับพ่อยองอู) / Twenty-Five Twenty-One / Our Beloved Summer · ☕ คาเฟ่ไฮไลท์: Paletscent (팔레트센트) รูฟท็อปวิวประตูจางอันมุน+แนวกำแพง 180° สวยสุดช่วงบ่าย-เย็น · Keep That Coffee (킵댓커피) ขึ้นชื่อลาเต้อาร์ต · Butterbook (버터북) โดนัทไส้ครีม/สโคน โทนเหลืองพาสเทล · 🛍️ ร้านของกระจุกกระจิก: Tabi (타비) · Space One (스페이스원) · Ogu Ogu · เดินถึงพระราชวังแฮงกุงปลายถนนได้เลย · ⚠️ ร้านเล็กหลายร้านปิดวันจันทร์ ไปวันธรรมดาอื่นจะเปิดครบกว่า'),
    ('suwon-starfield-library', 'หอคอยหนังสือสูง 22 ม. กินพื้นที่ชั้น 4-7 จุดถ่ายรูปหลักของ Starfield Suwon (แลนด์มาร์กใหม่ เปิดปี 2024 ใหญ่กว่าสาขา COEX) — ถ่ายจากชั้น 5-6 ขึ้นไปได้มุมกว้างสุด · ห้างเปิด 10:00-22:00 ทุกวัน · ☕ Vinyl Starfield ชั้น 8 คาเฟ่แผ่นเสียง ใส่หูฟังฟังไวนิลมองวิวห้องสมุดจากมุมสูง · 🛍️ สตรีทแวร์เกาหลี Matin Kim / Musinsa Standard / Covernat / Low Classic · น้ำหอม Granhand · ของแต่งบ้าน Vinyl & Plastic · มีสระว่ายน้ำลอยฟ้า/สวนดาดฟ้าชั้นบนด้วย · เดินจากสถานีฮวาซอ (화서역 สาย 1) 400 ม. — เข้า-ออกซูวอนทางนี้ตรงกว่าสถานีซูวอน'),
    ('suwon-hwahongmun', 'ประตูระบายน้ำโบราณสไตล์จีนริมลำธาร จุดถ่ายรูปสวยของกำแพงฮวาซ็อง'),
    ('suwon-changnyongmun', 'ประตูตะวันออกของกำแพงฮวาซ็อง เปิดตลอด 24 ชม. ไม่มีค่าเข้า · ลานหญ้าหน้าประตูคือที่จอดบอลลูนฟลายอิงซูวอน (플라잉수원) ห่างไป 60 ม. ถ่ายรูปคู่บอลลูนได้ฟรี · ⚠️ บอลลูนขึ้นบิน 13:00-22:00 (จ-ศ) / 11:00-22:00 (ส-อา) และงดบินเมื่อลมแรง · เดินเลียบกำแพงไปฮวาฮงมุน 700 ม. ต่อไปประตูจางอันมุนได้อีก 400 ม.'),
    ('suwon-haenggung', 'วังพักร้อนของพระเจ้าจองโจ วังแฮงกุงที่ใหญ่ที่สุดที่เหลืออยู่ในเกาหลี ฉากซีรีส์ Moon Embracing the Sun / Deep Rooted Tree · เปิด 09:00-18:00 ทุกวัน (มีค่าเข้า) · อยู่ปลายถนนคาเฟ่แฮงลีดันกิลพอดี เดินต่อกันได้ · ลานหน้าวังมีการแสดงศิลปะการต่อสู้ 24 ท่า (무예24기) รอบ 11:00 อังคาร-อาทิตย์'),
    ('suwon-tongdak-street', 'ตรอกไก่ทอดกระทะใหญ่ต้นตำรับซูวอน อยู่ในตลาดจีดง เดินจากฮวาฮงมุนลงใต้ 900 ม. · ร้านส่วนใหญ่เปิด ~11:30-23:00 · ⚠️ สองเจ้าดังหยุดคนละวัน: **จินมีทงดัก 진미통닭** (정조로800번길 21) ปิดวันจันทร์ · **ยงซองทงดัก 용성통닭** (정조로800번길 15) ปิดวันอังคาร — เลือกให้ตรงวันที่ไป · สั่งไก่ทอด 1 ตัวคู่เบียร์/น้ำอัดลม กินได้ 2 คน');

insert into public.catalog_place_descriptions (place_id, locale, description, source)
select p.id, 'th', d.description, 'curated'
  from _pd d
  join public.catalog_places p on p.legacy_slug = d.slug
on conflict (place_id, locale) do nothing;

do $verify$
declare n_want int; n_got int; n_miss int; n_empty int;
begin
  select count(*) into n_want from _pd;
  select count(*) into n_got
    from public.catalog_place_descriptions c
    join public.catalog_places p on p.id = c.place_id
    join _pd d on d.slug = p.legacy_slug
   where c.locale = 'th';

  if n_want <> 72 then raise exception 'ตารางชั่วคราวมี % แถว ไม่ใช่ 72 — สคริปต์ดึงข้อมูลผิด', n_want; end if;
  if n_got  <> 72 then raise exception 'คำบรรยายลงไม่ครบ: % ไม่ใช่ 72', n_got; end if;

  -- 🔴 เคสที่บอก *ทำไม* ถ้าไม่ครบ — join พลาดเพราะ slug ไม่ตรง จะเงียบสนิทถ้าไม่มีเคสนี้
  select count(*) into n_miss
    from _pd d
   where not exists (select 1 from public.catalog_places p where p.legacy_slug = d.slug);
  if n_miss <> 0 then raise exception 'มี % slug ที่หาไม่เจอในคลัง — data/places.ts กับคลังไม่ตรงกัน', n_miss; end if;

  -- 🔴 กันของว่าง: ถ้าเนื้อหลุดหายระหว่างทาง จะได้แถวครบแต่ไม่มีข้อความ
  select count(*) into n_empty
    from public.catalog_place_descriptions c
    join public.catalog_places p on p.id = c.place_id
    join _pd d on d.slug = p.legacy_slug
   where c.locale = 'th' and length(trim(c.description)) < 10;
  if n_empty <> 0 then raise exception 'มี % แถวที่คำบรรยายสั้นผิดปกติ (<10 ตัวอักษร)', n_empty; end if;

  raise notice 'คำบรรยายไทย % แถว · ยาวเฉลี่ย % ตัวอักษร', n_got,
    (select round(avg(length(description))) from public.catalog_place_descriptions where locale = 'th');
end $verify$;

commit;
